/* 학습 해설
 * XCTR·변환·상태와 적용 조건
 * Counter를 IV에 더하는 대신 XOR하는 구성은 CTR과 같은 keystream 목적이어도 다른 block 입력을 만듭니다.
 * XCTR는 16byte block index를 little-endian u32로 표현해 IV의 해당 byte에 XOR하고 block cipher encrypt 결과를 data와 XOR합니다. 각 block 뒤 counter XOR를 다시 수행해 IV를 복원하고 index를 증가시킵니다. HCTR2 구성 요소와 독립 인증 기능을 구분합니다.
 * 해당 template·consumer의 IV·block counter·최대 길이 규약을 따릅니다. Byte offset을 block index로 변환하는 식과 first counter 1을 맞추고 같은 key·keystream 재사용을 피합니다. 일반 CTR 형식과 교환하지 않습니다.
 */
static int crypto_xctr_crypt_segment(struct skcipher_walk *walk,
				    struct crypto_cipher *tfm, u32 byte_ctr)
{
	void (*fn)(struct crypto_tfm *, u8 *, const u8 *) =
		   crypto_cipher_alg(tfm)->cia_encrypt;
	const u8 *src = walk->src.virt.addr;
	u8 *dst = walk->dst.virt.addr;
	unsigned int nbytes = walk->nbytes;
	__le32 ctr32 = cpu_to_le32(byte_ctr / XCTR_BLOCKSIZE + 1);

	do {
		crypto_xor(walk->iv, (u8 *)&ctr32, sizeof(ctr32));
		fn(crypto_cipher_tfm(tfm), dst, walk->iv);
		crypto_xor(dst, src, XCTR_BLOCKSIZE);
		crypto_xor(walk->iv, (u8 *)&ctr32, sizeof(ctr32));

		le32_add_cpu(&ctr32, 1);

		src += XCTR_BLOCKSIZE;
		dst += XCTR_BLOCKSIZE;
	} while ((nbytes -= XCTR_BLOCKSIZE) >= XCTR_BLOCKSIZE);

	return nbytes;
}

