/* 학습 해설
 * Jitterentropy·변환·상태와 적용 조건
 * 실행 시간의 작은 변동을 난수 원천으로 사용할 때 측정 실패·건강 검사를 결과 출력과 함께 다뤄야 합니다.
 * Jitterentropy는 timing delta와 그 변화·memory access 등을 측정하고 stuck 판정·repetition count test·adaptive proportion test와 conditioning을 연결합니다. 측정 횟수가 곧 보장 entropy bit 수가 아니며 health failure면 출력 요청을 오류로 끝낼 수 있습니다.
 * Kernel RNG wrapper와 collector 초기화·oversampling·health 조건을 따릅니다. jent_read_entropy의 오류를 검사하고 실패한 instance의 재사용·재초기화 규약을 지킵니다. 단순 timestamp나 rand()를 동일한 원천으로 대체하지 않습니다.
 */
int jent_read_entropy(struct rand_data *ec, unsigned char *data,
		      unsigned int len)
{
	unsigned char *p = data;

	if (!ec)
		return -1;

	while (len > 0) {
		unsigned int tocopy, health_test_result;

		jent_gen_entropy(ec);

		health_test_result = jent_health_failure(ec);
		if (health_test_result > JENT_PERMANENT_FAILURE_SHIFT) {
			/*
			 * At this point, the Jitter RNG instance is considered
			 * as a failed instance. There is no rerun of the
			 * startup test any more, because the caller
			 * is assumed to not further use this instance.
			 */
			return -3;
		} else if (health_test_result) {
			/*
			 * Perform startup health tests and return permanent
			 * error if it fails.
			 */

