/* 학습 해설
 * arc·아키텍처별 부팅·예외·주소 공간
 * ARC platform의 bootloader 인자·CPU 준비·메모리 구성 순서를 공통 초기화와 연결해 볼 수 있습니다.
 * ARC setup은 U-Boot 인자를 처리하고 early parameter·machine init_early·SMP CPU 정보를 준비합니다. Processor와 memory 설정 뒤 flat Device Tree를 복사해 runtime tree로 펼칩니다. CPU ISA 선택과 board description은 별도이며 MMU·exception 코드는 해당 ARC configuration을 따릅니다.
 * 지원 ARC ISA·machine·DTB·toolchain을 맞추고 setup.c에서 memory·entry·IRQ 파일로 따라갑니다. 초기 flat tree 수명과 일반 device probe 시점을 구분하며 다른 ISA의 binary를 직접 실행하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	handle_uboot_args();

	/* Save unparsed command line copy for /proc/cmdline */
	*cmdline_p = boot_command_line;

	/* To force early parsing of things like mem=xxx */
	parse_early_param();

	/* Platform/board specific: e.g. early console registration */
	if (machine_desc->init_early)
		machine_desc->init_early();

	smp_init_cpus();

	setup_processor();
	setup_arch_memory();

	/* copy flat DT out of .init and then unflatten it */
	unflatten_and_copy_device_tree();

	/* Can be issue if someone passes cmd line arg "ro"
	 * But that is unlikely so keeping it as it is
	 */
	root_mountflags &= ~MS_RDONLY;

/* 학습 해설
 * arm·아키텍처별 부팅·예외·주소 공간
 * 32bit ARM의 오래된 ATAGS 경로와 Device Tree 경로를 비교하면 boot 정보 방식의 변화가 드러납니다.
 * ARM setup은 processor를 확인하고 전달된 pointer를 FDT로 해석해 machine description을 찾거나 ATAGS 기반 경로로 fallback합니다. 선택한 machine의 memory·DMA zone·paging·SMP operations를 연결합니다. ARM32의 ABI·exception entry와 ARM64의 exception level·table 구조는 구분해야 합니다.
 * 지원 ARM board·DTB·CPU configuration을 맞추고 head.S·setup_machine_fdt/tags·paging_init을 읽습니다. 실제 bootloader register 인계와 reserved DT memory·initrd·SMP 전제를 확인하며 모든 ARM platform에 같은 물리 map을 적용하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	const struct machine_desc *mdesc = NULL;
	void *atags_vaddr = NULL;

	if (__atags_pointer)
		atags_vaddr = FDT_VIRT_BASE(__atags_pointer);

	setup_processor();
	if (atags_vaddr) {
		mdesc = setup_machine_fdt(atags_vaddr);
		if (mdesc)
			memblock_reserve(__atags_pointer,
					 fdt_totalsize(atags_vaddr));
	}
	if (!mdesc)
		mdesc = setup_machine_tags(atags_vaddr, __machine_arch_type);
	if (!mdesc) {
		early_print("\nError: invalid dtb and unrecognized/unsupported machine ID\n");
		early_print("  r1=0x%08x, r2=0x%08x\n", __machine_arch_type,
			    __atags_pointer);
		if (__atags_pointer)
			early_print("  r2[]=%*ph\n", 16, atags_vaddr);
		dump_machine_table();
	}

/* 학습 해설
 * arm64·아키텍처별 부팅·예외·주소 공간
 * ARM64 초기 mapping·exception mask·firmware 선택이 정상 task 실행의 전제가 되는 과정을 연결할 수 있습니다.
 * ARM64 setup은 initial init_mm·KASLR·fixmap/ioremap·FDT와 static key를 준비하고 DAIF mask의 필요한 조건을 맞춥니다. Boot identity map 제거 뒤 memblock·paging·ACPI/DT·PSCI·CPU ops로 이어집니다. EL0/EL1과 firmware·hypervisor level 경계는 assembly entry와 함께 읽어야 합니다.
 * 지원 machine의 boot protocol·DT/ACPI·EFI·PSCI·CPU feature를 맞춥니다. TTBR·page granule·exception vector를 해당 configuration에서 확인하고 초기 idmap을 일반 user mapping으로 취급하지 않습니다.
 */
void __init __no_sanitize_address setup_arch(char **cmdline_p)
{
	setup_initial_init_mm(_stext, _etext, _edata, _end);

	*cmdline_p = boot_command_line;

	kaslr_init();

	early_fixmap_init();
	early_ioremap_init();

	setup_machine_fdt(__fdt_pointer);

	/*
	 * Initialise the static keys early as they may be enabled by the
	 * cpufeature code and early parameters.
	 */
	jump_label_init();
	parse_early_param();

	dynamic_scs_init();

	/*
	 * The primary CPU enters the kernel with all DAIF exceptions masked.
	 *
	 * We must unmask Debug and SError before preemption or scheduling is
	 * possible to ensure that these are consistently unmasked across
	 * threads, and we want to unmask SError as soon as possible after
	 * initializing earlycon so that we can report any SErrors immediately.
	 *
	 * IRQ and FIQ will be unmasked after the root irqchip has been
	 * detected and initialized.
	 */

