#ifdef CONFIG_HIGHMEM

/* 학습 해설
 * hexagon·아키텍처별 부팅·예외·주소 공간
 * DSP 계열 architecture에서 virtual machine interface·event binding이 boot 초기화와 연결되는 모습을 볼 수 있습니다.
 * Hexagon setup은 clock 관련 초기 값과 VM event vector를 준비하고 simulator 조건·command line·memory·CPU 시작을 처리합니다. __vmsetvec은 해당 architecture의 event binding을 연결하며 PC의 IDT와 같은 byte 형식이 아닙니다. Source의 고정 초기 값과 실제 hardware 능력은 구분합니다.
 * v6.12 Hexagon의 지원 VM·machine·toolchain과 entry·vm interface 문맥을 읽습니다. Simulator-specific 검사와 실제 hardware boot를 구분하고 고정 frequency를 모든 device의 보장된 측정치로 사용하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	char *p = &external_cmdline_buffer;

	/*
	 * These will eventually be pulled in via either some hypervisor
	 * or devicetree description.  Hardwiring for now.
	 */
	pcycle_freq_mhz = 600;
	thread_freq_mhz = 100;
	sleep_clk_freq = 32000;

	/*
	 * Set up event bindings to handle exceptions and interrupts.
	 */
	__vmsetvec(_K_VM_event_vector);

	printk(KERN_INFO "PHYS_OFFSET=0x%08lx\n", PHYS_OFFSET);

	/*
	 * Simulator has a few differences from the hardware.
	 * For now, check uninitialized-but-mapped memory
	 * prior to invoking setup_arch_memory().
	 */
	if (*(int *)((unsigned long)_end + 8) == 0x1f1f1f1f)
		on_simulator = 1;

/* 학습 해설
 * loongarch·아키텍처별 부팅·예외·주소 공간
 * LoongArch의 CPU 탐지·firmware·page table 준비와 공통 allocator의 연결 순서를 이해할 수 있습니다.
 * LoongArch setup은 cpu_probe·unwind, 환경·EFI·FDT, memblock·초기 page table과 boot command line을 준비합니다. Initrd 예약·platform memory/resource·SMP·paging으로 이어지며 해당 architecture의 CSR·exception·TLB 코드는 공통 VM API와 연결됩니다.
 * 지원 LoongArch platform의 ABI·boot protocol·EFI/DT·CPU config를 맞춥니다. Physical memory 예약·초기 pagetable·최종 paging의 역할을 나누고 이름이 비슷한 MIPS binary ABI로 대체하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	cpu_probe();
	unwind_init();

	init_environ();
	efi_init();
	fdt_setup();
	memblock_init();
	pagetable_init();
	bootcmdline_init(cmdline_p);
	parse_early_param();
	reserve_initrd_mem();

	platform_init();
	arch_mem_init(cmdline_p);

	resource_init();
	jump_label_init(); /* Initialise the static keys for paravirtualization */

#ifdef CONFIG_SMP
	plat_smp_setup();
	prefill_possible_map();
#endif

	paging_init();

