/* 학습 해설
 * microblaze·아키텍처별 부팅·예외·주소 공간
 * FPGA의 soft processor도 구성된 CPU·cache·memory·장치 description에 맞는 kernel 준비가 필요합니다.
 * MicroBlaze setup은 memory·command line·Device Tree·CPU 정보·cache·PCI를 순서대로 준비합니다. FPGA 안의 CPU configuration과 peripheral 배치가 kernel config·DT와 맞아야 하며 MMU·exception·cache 구현은 선택된 core 기능을 따릅니다. FPGA image와 Linux kernel image는 역할이 다릅니다.
 * 대상 MicroBlaze hardware config·DTB·toolchain·MMU 지원을 맞춥니다. setup_memory·setup_cpuinfo·cache helper와 entry를 따라가고 soft core라는 이유로 모든 hardware 기능이 runtime에 자동 탐지된다고 가정하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	*cmdline_p = boot_command_line;

	setup_memory();

	console_verbose();

	unflatten_device_tree();

	setup_cpuinfo();

	microblaze_cache_init();

	xilinx_pci_init();
}

