/* 학습 해설
 * mips·아키텍처별 부팅·예외·주소 공간
 * MIPS의 다양한 CPU·firmware·cache·TLB 변형을 한 공통 architecture 경로가 어떻게 선택하는지 볼 수 있습니다.
 * MIPS setup은 CPU·coherence manager 탐지와 PROM 인계 뒤 platform memory·resource·SMP·CPU cache·paging을 준비합니다. R4K 계열 TLB에는 entryhi·entrylo·ASID·wired entry 등 architecture-specific 규약이 있으며 모든 MIPS CPU가 같은 TLB 구현을 쓰는 것은 아닙니다.
 * 지원 MIPS CPU·endian·ABI·board boot format을 맞추고 cpu_probe·prom_init·TLB helper의 configuration을 확인합니다. 일반 VM 설명을 실제 register·exception refill 경로와 연결하되 한 CPU의 quirk를 전체 계열 규칙으로 확대하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	cpu_probe();
	mips_cm_probe();
	prom_init();

	setup_early_fdc_console();
#ifdef CONFIG_EARLY_PRINTK
	setup_early_printk();
#endif
	cpu_report();
	if (IS_ENABLED(CONFIG_CPU_R4X00_BUGS64))
		check_bugs64_early();

	arch_mem_init(cmdline_p);
	dmi_setup();

	resource_init();
	plat_smp_setup();
	prefill_possible_map();

	cpu_cache_init();
	paging_init();

	memblock_dump_all();

/* 학습 해설
 * nios2·아키텍처별 부팅·예외·주소 공간
 * Soft processor의 exception handler 위치가 CPU description과 memory 예약에 어떻게 연결되는지 볼 수 있습니다.
 * Nios II setup은 DRAM 범위·initial init_mm·page 한도와 kernel/initrd/DT reserved memory를 준비합니다. CPU info 뒤 exception handler와 fast TLB miss handler를 지정 주소에 복사하고 MMU context·paging을 초기화합니다. Handler code·주소·cache 조건은 선택한 core 규약을 따릅니다.
 * v6.12 대상 Nios II core·DTB·toolchain·exception 위치를 맞추고 source의 memory reserve와 handler copy 순서를 읽습니다. 다른 soft processor의 boot ABI로 바꾸지 않으며 source 존재와 현재 제품 지원 여부를 별도로 봅니다.
 */
void __init setup_arch(char **cmdline_p)
{
	console_verbose();

	memory_start = memblock_start_of_DRAM();
	memory_end = memblock_end_of_DRAM();

	setup_initial_init_mm(_stext, _etext, _edata, _end);
	init_task.thread.kregs = &fake_regs;

	/* Keep a copy of command line */
	*cmdline_p = boot_command_line;

	find_limits(&min_low_pfn, &max_low_pfn, &max_pfn);
	max_mapnr = max_low_pfn;

	memblock_reserve(__pa_symbol(_stext), _end - _stext);
#ifdef CONFIG_BLK_DEV_INITRD
	if (initrd_start) {
		memblock_reserve(virt_to_phys((void *)initrd_start),
				initrd_end - initrd_start);
	}
#endif /* CONFIG_BLK_DEV_INITRD */

	early_init_fdt_reserve_self();
	early_init_fdt_scan_reserved_mem();

/* 학습 해설
 * openrisc·아키텍처별 부팅·예외·주소 공간
 * OpenRISC의 초기 memory와 DT·CPU 준비를 공통 init_mm·paging과 연결해 이해할 수 있습니다.
 * OpenRISC setup은 memblock용 memory 준비 뒤 DT 복사·CPU 정보·조건부 SMP를 초기화합니다. Kernel의 초기 memory descriptor와 initrd 범위를 확인한 뒤 paging으로 진행합니다. Exception·MMU·TLB 진입은 arch/openrisc 하위 코드가 제공하며 ISA 개방성과 실행 중 privilege 보호는 다른 개념입니다.
 * 지원 OpenRISC machine·DTB·MMU config·toolchain을 맞추고 head·setup_memory·paging·fault handler를 따라갑니다. Initrd의 시작·끝 조건과 주소 단위를 확인하고 open ISA를 모든 앱의 kernel 접근 허용으로 해석하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	/* setup memblock allocator */
	setup_memory();

	unflatten_and_copy_device_tree();

	setup_cpuinfo();

#ifdef CONFIG_SMP
	smp_init_cpus();
#endif

	/* process 1's initial memory region is the kernel code/data */
	setup_initial_init_mm(_stext, _etext, _edata, _end);

#ifdef CONFIG_BLK_DEV_INITRD
	if (initrd_start == initrd_end) {
		printk(KERN_INFO "Initial ramdisk not found\n");
		initrd_start = 0;
		initrd_end = 0;
	} else {
		printk(KERN_INFO "Initial ramdisk at: 0x%p (%lu bytes)\n",
		       (void *)(initrd_start), initrd_end - initrd_start);
		initrd_below_start_ok = 1;
	}

/* 학습 해설
 * parisc·아키텍처별 부팅·예외·주소 공간
 * PA-RISC firmware 호출과 초기 kernel mapping 한도가 memory 탐지의 전제가 되는 사례를 볼 수 있습니다.
 * PA-RISC setup은 unwind·per-CPU mode/FPU, 초기 mapping 범위 검사 뒤 PDC firmware와 command line·CPU 정보를 준비합니다. Physical memory inventory·cache·paging·DMA operations가 이어집니다. 32/64bit config와 narrow firmware 경계를 다루며 page 크기는 선택된 kernel configuration을 따릅니다.
 * 지원 PA-RISC machine의 firmware·ABI·page 설정을 맞추고 PDC 호출·memory inventory·exception 진입을 읽습니다. Kernel image가 initial mapping 안에 있는지와 firmware pointer 폭을 확인하며 PC BIOS format을 적용하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	unwind_init();

	init_per_cpu(smp_processor_id());	/* Set Modes & Enable FP */

#ifdef CONFIG_64BIT
