#ifdef CONFIG_HUGETLB_PAGE
	printk(KERN_CONT "enabled with %d MB physical and %d MB virtual size",
		 1 << (REAL_HPAGE_SHIFT - 20), 1 << (HPAGE_SHIFT - 20));
#else
	printk(KERN_CONT "disabled");
#endif
	printk(KERN_CONT ".\n");

	/*
	 * Check if initial kernel page mappings are sufficient.
	 * panic early if not, else we may access kernel functions
	 * and variables which can't be reached.
	 */

/* 학습 해설
 * powerpc·아키텍처별 부팅·예외·주소 공간
 * PowerPC 계열의 다양한 platform callback·CPU topology·MMU 변형을 공통 준비와 나누어 읽을 수 있습니다.
 * PowerPC common setup은 DT·cache info·RTAS·machine 선택과 SMP topology를 준비하고 초기 MM·IRQ/emergency stack·memory와 platform setup_arch callback을 연결합니다. Book3S/BookE·hash/radix 등 MMU 변형은 config·CPU 조건의 하위 구현이며 모든 PowerPC에 한 page table 형식을 가정하지 않습니다.
 * 대상 PowerPC ABI·endian·MMU·firmware·machine config를 맞춥니다. setup-common과 setup_32/64·head·platform ppc_md operations를 연결하고 guest RTAS·hypervisor 경계를 일반 hardware register 접근과 구분합니다.
 */
void __init setup_arch(char **cmdline_p)
{
	kasan_init();

	*cmdline_p = boot_command_line;

	/* Set a half-reasonable default so udelay does something sensible */
	loops_per_jiffy = 500000000 / HZ;

	/* Unflatten the device-tree passed by prom_init or kexec */
	unflatten_device_tree();

	/*
	 * Initialize cache line/block info from device-tree (on ppc64) or
