	 */
	initialize_cache_info();

	/* Initialize RTAS if available. */
	rtas_initialize();

	/* Check if we have an initrd provided via the device-tree. */
	check_for_initrd();

	/* Probe the machine type, establish ppc_md. */
	probe_machine();

/* 학습 해설
 * riscv·아키텍처별 부팅·예외·주소 공간
 * RISC-V의 SBI 인계와 ISA extension 확인을 kernel의 memory·SMP 초기화와 연결할 수 있습니다.
 * RISC-V setup은 DT·initial init_mm·early ioremap과 SBI를 준비한 뒤 EFI·paging·ACPI/DT·memory·SMP·ISA capability를 초기화합니다. S-mode kernel의 firmware 호출과 trap/page table 규약은 M-mode 또는 hypervisor 역할과 구분하며 extension마다 cache·DMA·user ISA 조건이 달라집니다.
 * 대상 RISC-V ABI·ISA extensions·SBI·boot DT/ACPI·MMU mode를 맞춥니다. head·entry·SBI·satp/TLB helper를 이어 읽고 모든 구현이 같은 선택 extension을 지원한다고 가정하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	parse_dtb();
	setup_initial_init_mm(_stext, _etext, _edata, _end);

	*cmdline_p = boot_command_line;

	early_ioremap_setup();
	sbi_init();
	jump_label_init();
	parse_early_param();

	efi_init();
	paging_init();

	/* Parse the ACPI tables for possible boot-time configuration */
	acpi_boot_table_init();

#if IS_ENABLED(CONFIG_BUILTIN_DTB)
	unflatten_and_copy_device_tree();
#else
	unflatten_device_tree();
#endif
	misc_mem_init();

	init_resources();

/* 학습 해설
 * s390·아키텍처별 부팅·예외·주소 공간
 * Mainframe 계열의 IPL·Lowcore·facility와 실행 환경을 공통 kernel 준비와 연결할 수 있습니다.
 * s390 setup은 z/VM·KVM·LPAR 등의 machine 상태를 확인하고 IPL·OS info·memory와 kernel/initrd/lowcore를 예약합니다. Lowcore는 interruption 정보와 진입 상태의 architecture 구조이고 control registers·CPU facility·paging을 준비합니다. LPAR를 일반 user process와 같은 격리 계층으로 취급하지 않습니다.
 * 지원 s390x machine·IPL image·guest 환경·facility·toolchain을 맞춥니다. Lowcore old/new PSW와 entry·control register·page table의 의미를 읽고 hardware format의 offset을 일반 C field 재배치로 바꾸지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
        /*
         * print what head.S has found out about the machine
         */
	if (MACHINE_IS_VM)
		pr_info("Linux is running as a z/VM "
			"guest operating system in 64-bit mode\n");
	else if (MACHINE_IS_KVM)
		pr_info("Linux is running under KVM in 64-bit mode\n");
	else if (MACHINE_IS_LPAR)
		pr_info("Linux is running natively in 64-bit mode\n");
	else
		pr_info("Linux is running as a guest in 64-bit mode\n");

	if (have_relocated_lowcore())
		pr_info("Lowcore relocated to 0x%px\n", get_lowcore());

	log_component_list();

	/* Have one command line that is parsed and saved in /proc/cmdline */
	/* boot_command_line has been already set up in early.c */
	*cmdline_p = boot_command_line;

        ROOT_DEV = Root_RAM0;

/* 학습 해설
 * sh·아키텍처별 부팅·예외·주소 공간
 * SuperH boot parameter·MMU와 machine vector가 실제 kernel resource 범위에 연결되는 것을 볼 수 있습니다.
 * SH setup은 MMU를 켜고 boot parameter의 root·ramdisk 조건과 kernel text/data/BSS resource 범위를 준비합니다. Command line config·early device·machine vector·DT·paging·SMP가 이어집니다. CPU subtype·MMU·cache·platform operations는 선택한 configuration에 따라 다릅니다.
 * 지원 SH CPU·board·bootloader 인계·toolchain을 맞춥니다. Virt_to_phys resource·early console·machine vector와 fault/entry를 연결하며 boot readonly flag와 실제 filesystem write 권한을 같은 값으로 판단하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	enable_mmu();

	ROOT_DEV = old_decode_dev(ORIG_ROOT_DEV);

	printk(KERN_NOTICE "Boot params:\n"
			   "... MOUNT_ROOT_RDONLY - %08lx\n"
			   "... RAMDISK_FLAGS     - %08lx\n"
			   "... ORIG_ROOT_DEV     - %08lx\n"
			   "... LOADER_TYPE       - %08lx\n"
			   "... INITRD_START      - %08lx\n"
			   "... INITRD_SIZE       - %08lx\n",
			   MOUNT_ROOT_RDONLY, RAMDISK_FLAGS,
			   ORIG_ROOT_DEV, LOADER_TYPE,
			   INITRD_START, INITRD_SIZE);

#ifdef CONFIG_BLK_DEV_RAM
	rd_image_start = RAMDISK_FLAGS & RAMDISK_IMAGE_START_MASK;
#endif

	if (!MOUNT_ROOT_RDONLY)
		root_mountflags &= ~MS_RDONLY;
	setup_initial_init_mm(_text, _etext, _edata, _end);

	code_resource.start = virt_to_phys(_text);

/* 학습 해설
 * sparc·아키텍처별 부팅·예외·주소 공간
 * SPARC PROM·trap table·memory bank와 32/64bit 구현 분리를 boot 흐름으로 이해할 수 있습니다.
 * SPARC32 setup은 trapbase를 table로 연결하고 PROM command line·early console·CPU model을 확인합니다. Memory bank·MMU·root/initrd·per-CPU patch·paging과 possible CPU map을 준비합니다. SPARC64 setup_64.c와 register window·trap entry는 별도 구현 경로입니다.
 * 대상 SPARC32/64 machine·PROM·CPU model·toolchain을 맞추고 setup_32/64·entry·trap 코드를 비교합니다. 서로 다른 MMU model과 memory bank 구간을 확인하며 architecture 이름만으로 같은 binary format을 가정하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	int i;
	unsigned long highest_paddr;

	sparc_ttable = &trapbase[0];

	/* Initialize PROM console and command line. */
	*cmdline_p = prom_getbootargs();
	strscpy(boot_command_line, *cmdline_p, COMMAND_LINE_SIZE);
	parse_early_param();

	boot_flags_init(*cmdline_p);

	register_console(&prom_early_console);

	switch(sparc_cpu_model) {
	case sun4m:
		pr_info("ARCH: SUN4M\n");
		break;
	case sun4d:
		pr_info("ARCH: SUN4D\n");
		break;
	case sun4e:
		pr_info("ARCH: SUN4E\n");
		break;

/* 학습 해설
 * um·아키텍처별 부팅·예외·주소 공간
 * Linux kernel을 host 사용자 공간 프로세스로 실행하는 UML을 보면 guest OS와 host OS의 역할을 구분할 수 있습니다.
 * User-Mode Linux는 host process·memory mapping·system interface를 이용해 kernel과 guest task 실행을 지원합니다. Setup은 stack protection·guest physical memory 표현·DT/initrd·paging·host info·host randomness를 준비합니다. UML과 hardware virtualization KVM·container namespace는 같은 구현이 아닙니다.
 * 지원 host에서 ARCH=um 빌드와 UML boot 규약을 사용하고 guest memory·host backing·guest root image를 분리합니다. Host syscall·signal·mapping으로 연결되는 OS layer와 guest syscall 처리를 비교합니다.
 */
void __init setup_arch(char **cmdline_p)
{
	u8 rng_seed[32];

	stack_protections((unsigned long) &init_thread_info);
	setup_physmem(uml_physmem, uml_reserved, physmem_size, highmem);
	mem_total_pages(physmem_size, iomem_size, highmem);
	uml_dtb_init();
	read_initrd();

	paging_init();
	strscpy(boot_command_line, command_line, COMMAND_LINE_SIZE);
	*cmdline_p = command_line;
	setup_hostinfo(host_info, sizeof host_info);

	if (os_getrandom(rng_seed, sizeof(rng_seed), 0) == sizeof(rng_seed)) {
		add_bootloader_randomness(rng_seed, sizeof(rng_seed));
		memzero_explicit(rng_seed, sizeof(rng_seed));
	}
}

void __init arch_cpu_finalize_init(void)
{
	arch_check_bugs();
	os_check_bugs();
}

/* 학습 해설
 * x86·아키텍처별 부팅·예외·주소 공간
 * 익숙한 PC의 boot_params·메모리 지도·초기 trap과 정상 kernel mapping을 하나의 초기화 흐름으로 묶을 수 있습니다.
 * x86 setup은 32/64bit 조건에 맞는 initial page table·CPU 정보와 command line을 준비하고 early traps·CPU feature·static key/call·ioremap을 초기화합니다. Boot header·EFI·E820 memory map·예약 범위를 해석한 뒤 paging·ACPI 등으로 이어집니다. 같은 x86라도 BIOS/EFI·CPU quirk·page table config가 달라집니다.
 * 학습 VM의 x86 boot protocol·config·memory map을 확인하고 setup.c·head·entry·fault·page table helper를 연결합니다. E820 usable·reserved와 firmware field 길이를 검사하고 모든 map 항목을 allocator free RAM으로 사용하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
#ifdef CONFIG_X86_32
	memcpy(&boot_cpu_data, &new_cpu_data, sizeof(new_cpu_data));

	/*
	 * copy kernel address range established so far and switch
	 * to the proper swapper page table
	 */
	clone_pgd_range(swapper_pg_dir     + KERNEL_PGD_BOUNDARY,
			initial_page_table + KERNEL_PGD_BOUNDARY,
			KERNEL_PGD_PTRS);

	load_cr3(swapper_pg_dir);
	/*
	 * Note: Quark X1000 CPUs advertise PGE incorrectly and require
	 * a cr3 based tlb flush, so the following __flush_tlb_all()
	 * will not flush anything because the CPU quirk which clears
	 * X86_FEATURE_PGE has not been invoked yet. Though due to the
	 * load_cr3() above the TLB has been flushed already. The
	 * quirk is invoked before subsequent calls to __flush_tlb_all()
	 * so proper operation is guaranteed.
	 */
	__flush_tlb_all();
#else
	printk(KERN_INFO "Command line: %s\n", boot_command_line);

/* 학습 해설
 * xtensa·아키텍처별 부팅·예외·주소 공간
 * 구성 가능한 CPU의 실제 hardware config와 windowed ABI·exception vector 예약이 맞아야 합니다.
 * Xtensa setup은 hardware/build config ID를 비교하고 platform command line·initrd·kernel·여러 exception vector 범위를 예약합니다. MMU와 windowed call ABI 등의 core configuration은 mapping·register state·entry에 영향을 줍니다. Processor header는 MMU 설정에서 user 공간의 1GB 영역 전제를 설명합니다.
 * 대상 Xtensa core configuration·ABI·MMU·DT/platform·toolchain을 맞춥니다. Build ID와 실제 register 값·vector 위치·XIP memory 예약을 확인하고 임의 Xtensa kernel을 모든 구성의 core에서 호환 실행한다고 가정하지 않습니다.
 */
void __init setup_arch(char **cmdline_p)
{
	pr_info("config ID: %08x:%08x\n",
		xtensa_get_sr(SREG_EPC), xtensa_get_sr(SREG_EXCSAVE));
	if (xtensa_get_sr(SREG_EPC) != XCHAL_HW_CONFIGID0 ||
	    xtensa_get_sr(SREG_EXCSAVE) != XCHAL_HW_CONFIGID1)
		pr_info("built for config ID: %08x:%08x\n",
			XCHAL_HW_CONFIGID0, XCHAL_HW_CONFIGID1);

	*cmdline_p = command_line;
	platform_setup(cmdline_p);
	strscpy(boot_command_line, *cmdline_p, COMMAND_LINE_SIZE);

	/* Reserve some memory regions */

#ifdef CONFIG_BLK_DEV_INITRD
	if (initrd_start < initrd_end &&
	    !mem_reserve(__pa(initrd_start), __pa(initrd_end)))
		initrd_below_start_ok = 1;
	else
		initrd_start = 0;
#endif

	mem_reserve(__pa(_stext), __pa(_end));
#ifdef CONFIG_XIP_KERNEL
#ifdef CONFIG_VECTORS_ADDR

/* 학습 해설
 * TBF·시간으로 환산한 Token Bucket
 * 출력 속도와 허용 burst를 제한하려면 packet을 언제 보내도 되는지 시간과 크기로 계산해야 합니다.
 * TBF는 경과 시간만큼 credit을 보충하고 bucket 상한으로 제한한 뒤 packet 길이를 전송 시간으로 환산해 차감합니다. Rate bucket과 선택적인 peak bucket 모두 credit이 음수가 아닐 때만 dequeue합니다. 부족하면 watchdog을 예약하고 현재 packet 순서를 보존합니다.
 * 격리된 Linux 네트워크 namespace에서 tc로 rate·burst·limit을 설정하고 tc -s qdisc로 backlog·overlimits를 관찰합니다. Byte와 bit/s 단위, 장치 overhead, GSO 분할, 내부 child qdisc의 limit 계약을 함께 확인합니다.
 */
static struct sk_buff *tbf_dequeue(struct Qdisc *sch)
{
	struct tbf_sched_data *q = qdisc_priv(sch);
	struct sk_buff *skb;

	skb = q->qdisc->ops->peek(q->qdisc);

	if (skb) {
		s64 now;
